          agent: "backup",
          project: "core-db",
          duration: 210,
          model: "claude-4",
          time: "昨天 12:05",
          body: "数据库快照已生成并上传至对象存储，大小 1.2 GB。",
          link: "pi://session/sess_d9e7",
          sessionId: "sess_d9e71c",
          delivered: 4,
          total: 4,
        },
      ];

      const STATUS_META = {
        success: { dot: "dot-success", badge: "status-success", label: "成功" },
        error: { dot: "dot-error", badge: "status-error", label: "失败" },
        interrupted: { dot: "dot-warn", badge: "status-warn", label: "中断" },
      };

      // ===== 安全 DOM 构建工具（避免 innerHTML，防 XSS）=====
      function el(tag, attrs = {}, ...children) {
        const node = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs)) {
          if (k === "class") node.className = v;
          else if (k === "text") node.textContent = v;
          else if (k.startsWith("on"))
            node.addEventListener(k.slice(2).toLowerCase(), v);
          else node.setAttribute(k, v);
        }
        for (const c of children) {
          if (c == null) continue;
          node.append(c.nodeType ? c : document.createTextNode(c));
        }
        return node;
      }

      // ===== 渲染通知列表（DOM API，无 innerHTML）=====
      function renderNotifs(filter = "all") {
        const list = document.getElementById("notif-list");
        const rows = NOTIFICATIONS.filter(
          (n) => filter === "all" || n.status === filter,
        );
        list.replaceChildren(
          ...rows.map((n) => {
            const meta = STATUS_META[n.status];
            const btn = el(
              "button",
              {
                class:
                  "notif-row flex w-full items-center gap-4 px-6 py-4 text-left",
                onclick: () => openDetail(n.id),
              },
              el("span", { class: `dot ${meta.dot}` }),
              el(
                "div",
                { class: "min-w-0 flex-1" },
                el(
                  "div",
                  { class: "flex items-center gap-2" },
                  el("span", {
                    class: "truncate text-sm font-medium text-white",
                    text: n.title,
                  }),
                  el("span", {
                    class: `status-badge ${meta.badge}`,
                    text: meta.label,
                  }),
                ),
                el(
                  "div",
                  {
                    class:
                      "mt-0.5 flex items-center gap-2 text-xs text-zinc-500",
                  },
                  el("span", { class: "mono", text: n.agent }),
                  el("span", { class: "text-zinc-700", text: "·" }),
                  el("span", { class: "truncate", text: n.project }),
                  el("span", { class: "text-zinc-700", text: "·" }),
                  el("span", { text: `${n.duration}s` }),
                ),
              ),
              el(
                "div",
                { class: "flex shrink-0 flex-col items-end gap-1" },
                el("span", { class: "text-xs text-zinc-500", text: n.time }),
                el("span", {
                  class: "text-[10px] text-zinc-600",
                  text: `${n.delivered}/${n.total} 设备已送达`,
                }),
              ),
            );
            return btn;
          }),
        );
        document.getElementById("notif-count").textContent =
          `显示 ${rows.length} 条`;
      }

      // ===== 筛选 =====
      document.querySelectorAll(".filter-tab").forEach((tab) => {
        tab.addEventListener("click", () => {
          document
            .querySelectorAll(".filter-tab")
            .forEach((t) => t.classList.remove("active"));
          tab.classList.add("active");
          renderNotifs(tab.dataset.filter);
        });
      });
      renderNotifs();

      // ===== 通知详情（DOM API，无 innerHTML）=====
      function openDetail(id) {
        const n = NOTIFICATIONS.find((x) => x.id === id);
        const meta = STATUS_META[n.status];

        const head = document.getElementById("detail-head");
        head.replaceChildren(
          el("span", { class: `dot ${meta.dot}` }),
          el(
            "div",
            {},
            el("div", {
              class: "text-base font-medium text-white",
              text: n.title,
            }),
            el("div", {
              class: "text-xs text-zinc-500",
              text: `${n.project} · ${n.time}`,
            }),
          ),
        );

        const fields = [
          ["Agent", n.agent],
          ["会话", n.sessionId],
          ["模型", n.model],
          ["耗时", n.duration + "s"],
          ["状态", meta.label],
          ["送达", `${n.delivered}/${n.total} 设备`],
        ];
        const grid = el(
          "div",
          { class: "grid grid-cols-2 gap-3" },
          ...fields.map(([k, v]) =>
            el(
              "div",
              {
                class:
                  "rounded-lg bg-white/[0.03] px-3 py-2.5 ring-1 ring-white/[0.06]",
              },
              el("div", {
                class: "text-[10px] uppercase tracking-wide text-zinc-500",
                text: k,
              }),
              el("div", {
                class: "mono mt-0.5 text-[12px] text-zinc-200",
                text: v,
              }),
            ),
          ),
        );

        const linkIcon = document.createElementNS(
          "http://www.w3.org/2000/svg",
          "svg",
        );
        linkIcon.setAttribute("class", "h-4 w-4");
        linkIcon.setAttribute("viewBox", "0 0 24 24");
        linkIcon.setAttribute("fill", "none");
        linkIcon.setAttribute("stroke", "currentColor");
        linkIcon.setAttribute("stroke-width", "2");
        const linkPath = document.createElementNS(
          "http://www.w3.org/2000/svg",
          "path",
        );
        linkPath.setAttribute("d", "M7 17L17 7M7 7h10v10");
        linkIcon.appendChild(linkPath);

        const linkBtn = el(
          "a",
          {
            href: n.link,
            class:
              "btn-primary flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium",
          },
          "打开 Agent 会话",
          linkIcon,
        );

        document.getElementById("detail-body").replaceChildren(
          el("p", {
            class: "text-sm leading-relaxed text-zinc-300",
            text: n.body,
          }),
          grid,
          linkBtn,
        );
        document
          .getElementById("detail-modal")
          .classList.replace("hidden", "flex");
        document.body.style.overflow = "hidden";
      }
      function closeDetail() {
        document
          .getElementById("detail-modal")
          .classList.replace("flex", "hidden");
        document.body.style.overflow = "";
      }
      window.addEventListener("keydown", (e) => {
        if (e.key === "Escape") closeDetail();
      });

      // ===== 复制 =====
      function copyText(btn, sel) {
        const text = document.querySelector(sel).innerText;
        navigator.clipboard.writeText(text).then(() => {
          const orig = btn.textContent;
          btn.textContent = "已复制 ✓";
          setTimeout(() => (btn.textContent = orig), 1500);
        });
      }

      // ===== 侧边栏（移动端）=====
      const sidebar = document.getElementById("sidebar");
      const overlay = document.getElementById("sidebar-overlay");
      document.getElementById("menu-btn").addEventListener("click", () => {
        sidebar.classList.remove("-translate-x-full");
        overlay.classList.remove("hidden");
      });
      overlay.addEventListener("click", () => {
        sidebar.classList.add("-translate-x-full");
        overlay.classList.add("hidden");
      });

      // ===== 通知活动热力图（流式自适应，填充宽度、行列对齐）=====
      (function () {
        const hm = document.getElementById("hm");
        if (!hm) return;
        const LEVELS = [
          "rgba(255,255,255,0.05)",
          "var(--accent-1)",
          "var(--accent-2)",
          "var(--accent-3)",
          "var(--accent-4)",
        ];
        const WEEK_CN = ["日", "一", "二", "三", "四", "五", "六"];
        const WEEKS = 53;

        function seeded(str) {
          let h = 2166136261;
          for (let i = 0; i < str.length; i++) {
            h ^= str.charCodeAt(i);
            h = Math.imul(h, 16777619);
          }
          return function () {
            h ^= h << 13;
            h ^= h >>> 17;
            h ^= h << 5;
            return (h >>> 0) / 4294967296;
          };
        }
        function dayCount(date) {
          const r = seeded(date.toDateString());
          const dow = date.getDay();
          const weekend = dow === 0 || dow === 6;
          if (r() < (weekend ? 0.52 : 0.12)) return 0;
          const v = r();
          return Math.round((weekend ? 0.4 : 1) * (2 + v * v * 26));
        }
        function levelOf(c) {
          if (!c) return 0;
          if (c < 5) return 1;
          if (c < 10) return 2;
          if (c < 18) return 3;
          return 4;
        }

        const tip = document.createElement("div");
        tip.className = "hm-tip";
        document.body.append(tip);
        function showTip(cell, date, count) {
          const t1 = document.createElement("div");
          t1.className = "font-medium text-white";
          t1.textContent = count > 0 ? `${count} 条通知` : "无通知";
          const t2 = document.createElement("div");
          t2.className = "text-zinc-500";
          t2.textContent = `${date.getMonth() + 1}月${date.getDate()}日 周${WEEK_CN[date.getDay()]}`;
          tip.replaceChildren(t1, t2);
          const rect = cell.getBoundingClientRect();
          tip.style.left = rect.left + rect.width / 2 + "px";
          tip.style.top = rect.top + "px";
          tip.style.opacity = "1";
        }
        const hideTip = () => (tip.style.opacity = "0");

        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const dow = (today.getDay() + 6) % 7;
        const endMonday = new Date(today);
        endMonday.setDate(today.getDate() - dow);
        const startMonday = new Date(endMonday);
        startMonday.setDate(endMonday.getDate() - (WEEKS - 1) * 7);

        const DAY_LABELS = { 0: "一", 2: "三", 4: "五" };
        const frag = document.createDocumentFragment();
        for (let d = 0; d < 7; d++) {
          const s = document.createElement("span");
          s.className = "hm-day";
          s.style.gridRow = d + 2;
          s.textContent = DAY_LABELS[d] || "";
          frag.append(s);
        }

        let prevMonth = -1;
        for (let w = 0; w < WEEKS; w++) {
          const monday = new Date(startMonday);
          monday.setDate(startMonday.getDate() + w * 7);
          const m = monday.getMonth();
          if (m !== prevMonth) {
            const label = document.createElement("span");
            label.className = "hm-month";
            label.style.gridColumn = w + 2;
            label.textContent = `${m + 1}月`;
            frag.append(label);
            prevMonth = m;
          }
          for (let d = 0; d < 7; d++) {
            const date = new Date(monday);
            date.setDate(monday.getDate() + d);
            const future = date > today;
            const count = future ? 0 : dayCount(date);
            const cell = document.createElement("span");
            cell.className = "hm-cell";
            cell.style.gridColumn = w + 2;
            cell.style.gridRow = d + 2;
            if (future) {
              cell.dataset.future = "1";
            } else {
              cell.style.background = LEVELS[levelOf(count)];
              if (date.getTime() === today.getTime())
                cell.classList.add("hm-today");
              cell.addEventListener("mouseenter", () =>
                showTip(cell, date, count),
              );
              cell.addEventListener("mouseleave", hideTip);
            }
            frag.append(cell);
          }
        }
