        success: { dot: "dot-success", badge: "status-success", label: "成功" },
        error: { dot: "dot-error", badge: "status-error", label: "失败" },
        interrupted: { dot: "dot-warn", badge: "status-warn", label: "中断" },
      };

      // ===== 安全 DOM 构建工具（避免 innerHTML，防 XSS）=====
      function el(tag, attrs = {}, ...children) {
        const node = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs)) {
          if (k === "class") node.className = v;
          else if (k === "text") node.textContent = v;
          else if (k.startsWith("on"))
            node.addEventListener(k.slice(2).toLowerCase(), v);
          else node.setAttribute(k, v);
        }
        for (const c of children) {
          if (c == null) continue;
          node.append(c.nodeType ? c : document.createTextNode(c));
        }
        return node;
      }

      // ===== 渲染通知列表（DOM API，无 innerHTML）=====
      function renderNotifs(filter = "all") {
        const list = document.getElementById("notif-list");
        const rows = NOTIFICATIONS.filter(
          (n) => filter === "all" || n.status === filter,
        );
        list.replaceChildren(
          ...rows.map((n) => {
            const meta = STATUS_META[n.status];
            const btn = el(
              "button",
              {
                class:
                  "notif-row flex w-full items-center gap-4 px-6 py-4 text-left",
                onclick: () => openDetail(n.id),
              },
              el("span", { class: `dot ${meta.dot}` }),
              el(
                "div",
                { class: "min-w-0 flex-1" },
                el(
                  "div",
                  { class: "flex items-center gap-2" },
                  el("span", {
                    class: "truncate text-sm font-medium text-white",
                    text: n.title,
                  }),
                  el("span", {
                    class: `status-badge ${meta.badge}`,
                    text: meta.label,
                  }),
                ),
                el(
                  "div",
                  {
                    class:
                      "mt-0.5 flex items-center gap-2 text-xs text-zinc-500",
                  },
                  el("span", { class: "mono", text: n.agent }),
                  el("span", { class: "text-zinc-700", text: "·" }),
                  el("span", { class: "truncate", text: n.project }),
                  el("span", { class: "text-zinc-700", text: "·" }),
                  el("span", { text: `${n.duration}s` }),
                ),
              ),
              el(
                "div",
                { class: "flex shrink-0 flex-col items-end gap-1" },
                el("span", { class: "text-xs text-zinc-500", text: n.time }),
