      renderNotifs();

      // ===== 通知详情（DOM API，无 innerHTML）=====
      function openDetail(id) {
        const n = NOTIFICATIONS.find((x) => x.id === id);
        const meta = STATUS_META[n.status];

        const head = document.getElementById("detail-head");
        head.replaceChildren(
          el("span", { class: `dot ${meta.dot}` }),
          el(
            "div",
            {},
            el("div", {
              class: "text-base font-medium text-white",
              text: n.title,
            }),
            el("div", {
              class: "text-xs text-zinc-500",
              text: `${n.project} · ${n.time}`,
            }),
          ),
        );

        const fields = [
          ["Agent", n.agent],
          ["会话", n.sessionId],
          ["模型", n.model],
          ["耗时", n.duration + "s"],
          ["状态", meta.label],
          ["送达", `${n.delivered}/${n.total} 设备`],
        ];
        const grid = el(
          "div",
          { class: "grid grid-cols-2 gap-3" },
          ...fields.map(([k, v]) =>
            el(
              "div",
              {
                class:
                  "rounded-lg bg-white/[0.03] px-3 py-2.5 ring-1 ring-white/[0.06]",
              },
              el("div", {
